import{_ as o,C as i,c as r,o as n,j as t,G as s,ag as l,a as d}from"./chunks/framework.DZ_cNctr.js";const h="/docs/screenshots/ome-tiff-slide.webp",b=JSON.parse('{"title":"OME-TIFF Viewer","description":"Free online OME-TIFF viewer: open OME-TIFF files in your browser, with every channel, Z, time and 3D. From your disk or a link. Nothing to install.","frontmatter":{"title":"OME-TIFF Viewer","description":"Free online OME-TIFF viewer: open OME-TIFF files in your browser, with every channel, Z, time and 3D. From your disk or a link. Nothing to install."},"headers":[],"relativePath":"guides/ome-tiff.md","filePath":"guides/ome-tiff.md"}'),m={name:"guides/ome-tiff.md"};function p(f,e,c,u,g,w){const a=i("OpenViewer");return n(),r("div",null,[e[0]||(e[0]=t("h1",{id:"ome-tiff-viewer",tabindex:"-1"},[d("OME-TIFF Viewer "),t("a",{class:"header-anchor",href:"#ome-tiff-viewer","aria-label":'Permalink to "OME-TIFF Viewer"'},"​")],-1)),e[1]||(e[1]=t("p",null,"Open OME-TIFF files in your browser, with all their channels, Z planes and time points. The viewer reads only the part you look at, so a large file opens without reading all of it first.",-1)),s(a,{example:"https://find-nuclei.github.io/examples/formats/venus-stack.ome.tif",view3d:"z=33&c=0%3Aon%3AFFFFFF%3A30%3A2108%3A1.00&zm=0.12&xy=195%2C307&cm=C&inv=f&bg=%23000000&pj=none%3A0%3A49&l=&l3s=&mode=3d&layout=main&main=v3d&rm=composite&cam=303.9%2C291.3%2C61.59%2C2.028%2C-0.07653%2C-0.5409%2C0.8376%2C-0.1842%2C-0.8179%2C-0.5451&bri=1.202&ramp=0%3A150%3A1665",label:"a Z-stack of 67 planes"}),e[2]||(e[2]=l('<p><img src="'+h+'" alt="Leica-1.ome.tiff open in the viewer: an H&amp;E section in RGB"></p><h2 id="how-to-open-an-ome-tiff-file" tabindex="-1">How to Open an OME-TIFF File <a class="header-anchor" href="#how-to-open-an-ome-tiff-file" aria-label="Permalink to &quot;How to Open an OME-TIFF File&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Working with many files?</p><p>Chrome and Edge on a computer open a whole folder as a <a href="./many-images.html">gallery</a>. Firefox and Safari open one file at a time.</p></div><ul><li><strong>One file on your disk</strong>, in any browser. Drop it on <a href="https://find-nuclei.github.io/" target="_blank" rel="noreferrer">the viewer</a>, or click <strong>Open Image</strong> and <strong>Choose File</strong>. See <a href="./local-files.html#open-a-file">Local Files</a>.</li><li><strong>A folder of files</strong>, in Chrome and Edge. One file opens. Several show a list with a picture of each. After you pick one, a gallery of pictures under the image takes you to the next. See <a href="./many-images.html">Folders, Zips and Series</a>.</li><li><strong>An address</strong>: <code>https://</code>, <code>s3://</code> or <code>gs://</code>. Paste it under <strong>Open Image</strong>. See <a href="./remote-urls.html">Remote URLs</a>.</li><li><strong>Private data</strong>, with a private link or a token. See <a href="./authenticated-sources.html">Private Images and Slides</a>.</li></ul><p>A Z-stack can also be viewed in 3D, whichever of these it was opened from. See <a href="./3d-rendering.html#requirements-and-limits">3D Rendering</a>.</p><h2 id="what-you-will-see" tabindex="-1">What You Will See <a class="header-anchor" href="#what-you-will-see" aria-label="Permalink to &quot;What You Will See&quot;">​</a></h2><ul><li><strong>Lower resolutions.</strong> When the file has them, zooming out stays fast.</li><li><strong>Channels.</strong> Names and colours come from the file. RGB and multi-channel fluorescence both open.</li><li><strong>Z and time.</strong> Sliders step through the planes.</li><li><strong>3D.</strong> A Z-stack opens in 3D too, with XY, XZ and YZ planes and the volume. See <a href="./3d-rendering.html">3D Rendering</a>.</li><li><strong>Pixel types.</strong> 8, 16 and 32-bit integers and float.</li><li><strong>Compression.</strong> None, LZW, Deflate, PackBits, JPEG and JPEG 2000.</li><li><strong>Pixel size and magnification.</strong> The pixel size comes from the file, and the magnification from the objective it names. To set your own, see <a href="./calibration.html">Pixel Size and Magnification</a>.</li></ul><h2 id="if-a-file-does-not-open" tabindex="-1">If a File Does Not Open <a class="header-anchor" href="#if-a-file-does-not-open" aria-label="Permalink to &quot;If a File Does Not Open&quot;">​</a></h2><p>The viewer tells you why.</p><table tabindex="0"><thead><tr><th>What the file has</th><th>What the viewer says</th></tr></thead><tbody><tr><td>Planes kept in other files</td><td>This OME-TIFF keeps its planes in other files. The viewer reads one file for now.</td></tr><tr><td>Another compression, such as Zstd</td><td>This OME-TIFF uses a compression the viewer cannot read yet.</td></tr><tr><td>Another pixel type, such as double</td><td>This OME-TIFF has a pixel type the viewer cannot read yet.</td></tr><tr><td>Not an OME-TIFF</td><td>This file is not an OME-TIFF.</td></tr><tr><td>A damaged or incomplete file</td><td>This OME-TIFF looks damaged or incomplete.</td></tr></tbody></table><p>Label and overview images are left out, with a note.</p><h2 id="annotations" tabindex="-1">Annotations <a class="header-anchor" href="#annotations" aria-label="Permalink to &quot;Annotations&quot;">​</a></h2><p>Import GeoJSON or OME-XML, and export both, from the <strong>Annotations</strong> panel. Send a link that opens the slide with its annotations. <a href="./annotation-exchange.html">Exchanging Annotations</a> shows how. To draw, measure and label shapes on the slide, see <a href="./annotations.html">Annotations</a>.</p><h2 id="public-files-to-try" tabindex="-1">Public Files to Try <a class="header-anchor" href="#public-files-to-try" aria-label="Permalink to &quot;Public Files to Try&quot;">​</a></h2><p>The OME project publishes <a href="https://docs.openmicroscopy.org/ome-model/5.6.0/ome-tiff/data.html" target="_blank" rel="noreferrer">sample OME-TIFF files</a>, with pyramids under <a href="https://downloads.openmicroscopy.org/images/OME-TIFF/2016-06/sub-resolutions/" target="_blank" rel="noreferrer">sub-resolutions</a>.</p><h2 id="for-your-it-team" tabindex="-1">For Your IT Team <a class="header-anchor" href="#for-your-it-team" aria-label="Permalink to &quot;For Your IT Team&quot;">​</a></h2><p>To open a file by address, the server must answer byte-range requests and allow them through <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS" target="_blank" rel="noreferrer">CORS</a>. For a bucket, allow <code>GET</code> and the <code>Range</code> header in its CORS rules. <a href="./remote-urls.html#what-the-server-needs">What the Server Needs</a> has the details.</p><p>When a server cannot send parts of a file, the viewer says so. Download the file and open it from your computer.</p><p>Addresses that start with <code>s3://</code> and <code>gs://</code> work too.</p><h2 id="image-credits" tabindex="-1">Image credits <a class="header-anchor" href="#image-credits" aria-label="Permalink to &quot;Image credits&quot;">​</a></h2><p>The screenshot uses <code>Leica-1.ome.tiff</code>, a sample OME-TIFF file (c) the OME Consortium, CC BY 4.0, made from an OpenSlide Leica slide. See <a href="./../sample-data.html">Sample Data and Credits</a>.</p><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>The file is read in your browser. Opening one counts as one opened image of the kind &quot;OME-TIFF file&quot;. The file name and address are never recorded. See the <a href="https://find-nuclei.github.io/privacy.html" target="_blank" rel="noreferrer">privacy policy</a>.</p>',23))])}const y=o(m,[["render",p]]);export{b as __pageData,y as default};
